async function visitLedger(stream, visitor) {
  const reader = stream.getReader();
  let accepted = 0;
  let rejected = 0;
  let stopped = false;
  let reachedEof = false;
  let parts = [];
  const decoder = new TextDecoder("utf-8");

  async function visitLine(raw, line) {
    if (raw.charCodeAt(raw.length - 1) === 13) {
      raw = raw.slice(0, -1);
    }

    if (raw.trim().length === 0) {
      return true;
    }

    let value;
    try {
      value = JSON.parse(raw);
    } catch {
      rejected += 1;
      return true;
    }

    accepted += 1;
    if ((await visitor({ line, value })) === false) {
      stopped = true;
      return false;
    }

    return true;
  }

  async function consumeText(text, lineNumber) {
    let start = 0;

    for (let index = 0; index < text.length; index += 1) {
      if (text.charCodeAt(index) !== 10) {
        continue;
      }

      parts.push(text.slice(start, index));
      const raw = parts.length === 1 ? parts[0] : parts.join("");
      parts = [];

      if (!(await visitLine(raw, lineNumber.count))) {
        return false;
      }

      lineNumber.count += 1;
      start = index + 1;
    }

    if (start < text.length) {
      parts.push(text.slice(start));
    }

    return true;
  }

  try {
    const lineNumber = { count: 1 };

    while (true) {
      const { done, value } = await reader.read();

      if (done) {
        const tail = decoder.decode();

        if (!(await consumeText(tail, lineNumber))) {
          break;
        }

        if (parts.length > 0) {
          const raw = parts.length === 1 ? parts[0] : parts.join("");
          parts = [];

          if (!(await visitLine(raw, lineNumber.count))) {
            break;
          }
        }

        reachedEof = true;
        break;
      }

      const text = decoder.decode(value, { stream: true });
      if (!(await consumeText(text, lineNumber))) {
        break;
      }
    }

    return { accepted, rejected, stopped };
  } finally {
    if (!reachedEof) {
      await reader.cancel();
    }
    reader.releaseLock();
  }
}
